'use client';
import { useRouter } from 'next/navigation'; // ✅ use this in app directory
import { useState } from 'react';
import {
  FaSun, FaMoon, FaHeart, FaLaptopHouse, FaUser,
  FaUniversity, FaRobot
} from 'react-icons/fa';

export default function Dashboard() {
  const router = useRouter();
  const [darkMode, setDarkMode] = useState(false);
  const [activeSection, setActiveSection] = useState('Dashboard');

  return (
    <div className="">
      <div className="flex h-screen bg-blue-100 dark:bg-white">
        {/* Sidebar */}
        <aside className="w-52 bg-blue-950 text-white ps-4 flex flex-col relative shadow-md">
          <h2 className="text-xl font-bold py-6">Brain Wave</h2>
          <nav className="mt-5">
            <ul>
              {[
                { name: 'Profile', icon: <FaUser />, path: '/profile' },
                { name: 'Saved Posts', icon: <FaHeart />, path: '/saved-posts' },
                { name: 'Coworking', icon: <FaLaptopHouse />, path: '/coworking' },
                { name: 'University', icon: <FaUniversity />, path: '/university' },
                { name: 'AI', icon: <FaRobot />, path: '/ai' },
              ].map((item) => (
                <li
                  key={item.name}
                  className={`item flex items-center space-x-2 py-4 px-4 cursor-pointer transition-all duration-300 relative z-10 ${
                    activeSection === item.name
                      ? 'bg-white text-blue-950 rounded-l-full shadow-md'
                      : 'hover:bg-gray-100 hover:text-blue-950 rounded-l-full '
                  }`}
                  onClick={() => {
                    setActiveSection(item.name);
                    router.push(item.path);
                  }}
                >
                  <span>{item.icon}</span>
                  <span>{item.name}</span>
                </li>
              ))}
            </ul>
          </nav>
        </aside>

        {/* Main Content */}
        <main className="flex-1 p-6 bg-gray-100 text-black rounded-r-3xl shadow-md relative z-0">
          {/* Header */}
          <div className="flex justify-between items-center mb-5">
            <h1 className="text-2xl font-bold text-gray-900 ">{activeSection}</h1>
            <button
              onClick={() => setDarkMode(!darkMode)}
              className="p-2 rounded-full bg-gray-200 dark:bg-gray-700"
            >
              {darkMode ? <FaSun className="text-yellow-500" /> : <FaMoon className="text-gray-800" />}
            </button>
          </div>

          {/* Profile Box */}
          <div className="p-5 bg-gray-200 rounded-lg shadow mb-5">
            <h3 className="text-blue-950 text-xl font-bold ">Profile</h3>
            <div className="flex items-center space-x-4 mt-3">
              <div className="w-16 h-16 bg-gray-400 rounded-full"></div>
              <p className="text-blue-950 font-bold">Flen foulen</p>
            </div>
          </div>

          {/* Stats Grid */}
          <div className="grid grid-cols-4 gap-4">
            {[
              { title: 'Tasks to do', value: 10 },
              { title: 'Done tasks', value: 21 },
              { title: 'Meeting rooms', value: 2 },
              { title: 'Posts', value: '6' },
            ].map(stat => (
              <div key={stat.title} className="p-5 bg-gray-200 text-blue-950 rounded-lg shadow">
                <h3 className="text-lg text-gray-600">{stat.title}</h3>
                <p className="text-2xl font-bold text-gray-900">{stat.value}</p>
              </div>
            ))}
          </div>

          {/* Calendar Section */}
          <div className="mt-5 p-5 bg-gray-200 rounded-lg shadow">
            <h3 className="text-lg text-gray-600">Calendar</h3>
            <p className="text-gray-900 dark:text-gray-400">Your calendar</p>
          </div>

          {/* To-Do List */}
          <div className="mt-5 p-5 bg-gray-200 rounded-lg shadow">
            <h3 className="text-lg text-gray-600">The most important tasks To-Do</h3>
            <ul className="mt-3">
              <li className="text-gray-900">✔ First task</li>
              <li className="text-gray-900">✔ Second task</li>
              <li className="text-gray-900">✔ Third task</li>
            </ul>
          </div>
        </main>
      </div>
    </div>
  );
}
